import{_ as a,a as s,c as t,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Redis Stream（消息流） · 1. 定位：解决什么问题","description":"事件记录、消费组与比赛结果入库，包括基本操作、适用场景和使用边界。","frontmatter":{"title":"Redis Stream（消息流） · 1. 定位：解决什么问题","description":"事件记录、消费组与比赛结果入库，包括基本操作、适用场景和使用边界。","splitFrom":"middleware/redis/plus/subjects/stream.md","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis Stream（消息流）","summary":"事件记录、消费组与比赛结果入库，包括基本操作、适用场景和使用边界。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis Stream（消息流）","link":"/middleware/redis/plus/subjects/stream"},"next":{"text":"Redis Stream（消息流） · 2. 命令速查与示例","link":"/middleware/redis/plus/subjects/stream-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis Stream（消息流）","link":"/middleware/redis/plus/subjects/stream"},"next":{"text":"Redis Stream（消息流） · 2. 命令速查与示例","link":"/middleware/redis/plus/subjects/stream-part-02"}},"headers":[],"relativePath":"middleware/redis/plus/subjects/stream-part-01.md","filePath":"middleware/redis/plus/subjects/stream-part-01.md"}'),i={name:"middleware/redis/plus/subjects/stream-part-01.md"};function d(l,e,n,p,o,c){return s(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="redis-stream-消息流-·-1-定位-解决什么问题" tabindex="-1">Redis Stream（消息流） · 1. 定位：解决什么问题 <a class="header-anchor" href="#redis-stream-消息流-·-1-定位-解决什么问题" aria-label="Permalink to &quot;Redis Stream（消息流） · 1. 定位：解决什么问题&quot;">​</a></h1><p><a href="/middleware/redis/plus/subjects/stream">返回分篇目录</a></p><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="stream" tabindex="-1">Redis Stream（消息流） <a class="header-anchor" href="#stream" aria-label="Permalink to &quot;Redis Stream（消息流） {#stream}&quot;">​</a></h2><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="position" tabindex="-1">1. 定位：解决什么问题 <a class="header-anchor" href="#position" aria-label="Permalink to &quot;1. 定位：解决什么问题 {#position}&quot;">​</a></h2><p>Stream 是按条目 ID 组织的追加事件日志，提供游标读取和消费组。List 弹出后立即移除，Pub/Sub 不保留离线消息；需要事件重放、待确认状态与多个独立消费组时使用 Stream，但可靠性仍依赖持久化与消费流程。</p><h3 id="基本操作示例" tabindex="-1">基本操作示例 <a class="header-anchor" href="#基本操作示例" aria-label="Permalink to &quot;基本操作示例 {#基本操作示例}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XADD learn:types:events * action login user 42</span></span>
<span class="line"><span>XRANGE learn:types:events - + COUNT 1</span></span></code></pre></div><p><code>XADD</code> 返回自动生成的 ID，具体值随执行时间变化。消费组中的确认、待处理条目和故障后的接管需要配合设计；业务处理可能重复，仍需幂等性。应制定裁剪和保留策略，不能让事件无限增长。</p><p>参考：<a href="https://redis.io/docs/latest/develop/data-types/streams/" target="_blank" rel="noopener noreferrer">Stream</a>。</p><h3 id="比赛结果入库" tabindex="-1">比赛结果入库 <a class="header-anchor" href="#比赛结果入库" aria-label="Permalink to &quot;比赛结果入库 {#比赛结果入库}&quot;">​</a></h3><p>生产者追加比赛结果，消费者通过消费组领取，在数据库提交结果后再 <code>XACK</code>。用比赛 ID 或事件 ID 在数据库建立唯一约束：如果提交成功、确认前进程崩溃，重新投递的事件不能重复发奖或重复结算。</p><p>消息 ID 在一条流内有序，不是跨所有流的全局业务 ID。消费组的待处理记录也不会自动保证处理进程恢复，需要检查超时消息并接管。规划裁剪时要考虑未处理消息，Redis 持久化与备份策略同样影响可恢复性。</p><h3 id="聊天与事件广播" tabindex="-1">聊天与事件广播 <a class="header-anchor" href="#聊天与事件广播" aria-label="Permalink to &quot;聊天与事件广播 {#聊天与事件广播}&quot;">​</a></h3><p>Pub/Sub 是发布订阅能力，不是一个键值数据类型，适合允许丢失的实时广播。离线订阅者无法靠它重放消息。Stream 可保存事件和消费位置，但同一消费组中的消费者通常分工处理；若每个独立业务都需要完整事件流，应分别管理消费组或读取游标。</p>`,16)])])}const h=a(i,[["render",d]]);export{u as __pageData,h as default};
